<?php $products=$this->getVar('paymentProducts',array()); $csrf=htmlspecialchars($this->getVar('paymentCsrf',''),ENT_QUOTES,'UTF-8'); ?>
<section class="payment-workbench"><header><p class="eyebrow">MEMBERSHIP AND COURSE ACCESS</p><h1>Choose access</h1><p>Choose a membership or course. The amount shown here is fixed by the current published price.</p></header>
<?php if($this->getVar('paymentError','')):?><div class="error"><?=htmlspecialchars($this->getVar('paymentError'),ENT_QUOTES,'UTF-8')?></div><?php endif;?>
<div class="payment-product-grid"><?php foreach($products as $product): $price=$product['current_price']??null; if(!$price)continue; ?><article class="payment-product-card"><h2><?=htmlspecialchars($product['name'],ENT_QUOTES,'UTF-8')?></h2><p class="payment-price"><?=htmlspecialchars($price['currency'])?> <?=number_format(((int)$price['amount_minor'])/100,2)?></p><p><?=htmlspecialchars(ucwords(str_replace('_',' ',$product['billing_period'])))?></p><form method="post" action="<?=$this->uri(array('action'=>'buy'))?>"><input type="hidden" name="csrf_token" value="<?=$csrf?>"><input type="hidden" name="product_code" value="<?=htmlspecialchars($product['code'],ENT_QUOTES,'UTF-8')?>"><button class="button" type="submit">Continue to checkout</button></form></article><?php endforeach;?></div><?php if(!$products):?><p>No products are currently available.</p><?php endif;?></section>
